"""Original developer option labels and definitions; only terms used in the bank."""
TERMS = {}
def t(key, label, meaning):
    if key in TERMS: raise ValueError(f"Duplicate term: {key}")
    TERMS[key] = (label, meaning)

t('absent', 'Mark missing evidence and route for retrieval or review', 'Retries cannot recover a fact that the available document never contained. Use unknown status, authorized retrieval, clarification, or review instead of fabrication.')
t('abstain', 'State insufficient evidence or use an approved escalation path', 'Avoid fabricate unsupported consequential answers. Clarify, obtain authorized evidence, or escalate under the defined policy when approved context is inadequate.')
t('acceptance', 'Define observable acceptance criteria for required outcomes', 'Checkable success and failure conditions make a proposed behavior evaluable. Generic quality adjectives and technology choices do not establish acceptable results.')
t('acceptdev', 'A: $0.025 per accepted result', 'Under the simplified assumptions, A costs $0.02 / 0.8 = $0.025 per accepted result; B costs $0.015 / 0.5 = $0.03. Other costs can change the comparison.')
t('acceptdevb', 'B: $0.015 per accepted result', 'Call price is not accepted-result cost when only half of attempts are acceptable. Divide by the relevant acceptance rate.')
t('acceptdevtie', 'Both have identical accepted-result cost', 'Equal outcome cost requires equal price-to-acceptance ratios under the simplified assumptions, not merely similar call prices.')
t('acceptdevzero', 'Acceptance does not affect cost per accepted result', 'Failed attempts still consume resources, so acceptance matters when pricing verified outcomes.')
t('access', 'Apply requester permissions before evidence enters model context', 'Data access must be authorized externally. Retrieved content being internal or relevant does not justify showing it to every user.')
t('adapter', 'Use a provider-specific adapter behind a stable application interface', 'Different hosting providers can use distinct authentication, endpoints, identifiers, and supported features. Normalize the application contract without assuming identical wire protocols.')
t('adaptive', 'Map the problem and revise subtasks as evidence emerges', 'Open-ended investigation benefits from exploration, prioritized hypotheses, and revised decomposition rather than an exhaustive fixed script chosen before evidence.')
t('agentsdk', 'Evaluate the supported Claude Agent SDK', 'An agent SDK can provide supported orchestration capabilities while still requiring version-aware deployment, permissions, monitoring, and application controls.')
t('any', 'Use tool_choice with type any', 'Where supported, any requires a tool selection but leaves the specific tool to the model. It does not guarantee that a particular named tool runs.')
t('approval', 'Require authorized approval before the consequential action', 'Review must gate the external effect, be tied to the intended action, and use current authority. A later audit cannot reliably reverse a completed effect.')
t('assemble', 'Accumulate deltas by block index before final validation', 'Network chunks and content deltas can contain partial strings or JSON. Track event and block boundaries or use SDK helpers before consuming a complete structured value.')
t('async', 'Use asynchronous I/O with bounded concurrency', 'Await network operations without blocking an event loop, while limiting in-flight work and respecting service capacity. Creating a coroutine does not mean it has run.')
t('audit', 'Keep protected action and identity audit records', 'Audit records support attribution and reconstruction of consequential actions. Limit access, sensitive content, and retention; they do not themselves block an effect.')
t('auditconfidence', 'Sample high-confidence outputs within relevant strata', 'Ongoing random checks among high-confidence results can discover hidden errors and changing patterns that low-confidence-only review misses.')
t('authn', 'Authenticate the calling identity', 'Authentication establishes who is calling. Authorization separately decides what that identity may do to a particular resource.')
t('authz', 'Authorize the current identity for the actual target and action', 'Permission must be enforced in trusted code using current resource and business state. A valid login, JSON schema, or model proposal alone does not grant authority.')
t('auto', 'Use tool_choice with type auto', 'Auto permits either a tool call or an ordinary response. It cannot guarantee extraction through a tool on every request.')
t('backpressure', 'Bound work queues and apply backpressure', 'Limit queued and active work so slow consumers or provider limits do not exhaust memory or connections. Unbounded parallelism is not a capacity plan.')
t('bash', 'Use Bash for an authorized command with bounded execution', 'Command execution fits tests, builds, and similar tasks when authorized. It is more powerful than file search and needs explicit safety and runtime controls.')
t('batch', 'Use Message Batches for latency-tolerant independent requests', 'Asynchronous batches fit non-blocking workloads. The retrieved guide describes discounted processing and a window up to 24 hours, not a guaranteed latency SLA.')
t('bill018', '$0.18', 'A hundred-thousand token count is not a ten-thousand count. Convert usage to the specified billing unit before multiplying.')
t('bill18', '$18.00', 'Check the million-token denominator and decimal placement; a tenfold scaling mistake can inflate an otherwise correct sum.')
t('bill180', '$1.80', 'At hypothetical rates of $2 per million input tokens and $6 per million output tokens, 300,000 input and 200,000 output tokens cost $0.60 + $1.20 = $1.80.')
t('bill240', '$2.40', 'Input and output can have different rates. Apply each stated rate to its corresponding usage rather than use one rate for all tokens.')
t('blocks', 'Dispatch response content according to each block type', 'A response can contain text, tool use, thinking, or other supported blocks. Do not assume content is one string or that the first block is always displayable text.')
t('boundary', 'Isolate model-output defects from integration defects', 'Check whether correct raw output was lost or changed by serialization, parsing, routing, or persistence. Not every visible error is fixed by changing the prompt.')
t('budget', 'Enforce task, iteration, and spending safeguards', 'Budgets bound runaway execution but are separate from protocol-based completion. Reaching a budget should yield an explicit incomplete or escalation state.')
t('budgetcontext', 'Budget instructions, evidence, history, and generation together', 'Follow the chosen model and service limits. Overflow handling varies; it is not universally automatic oldest-message deletion.')
t('builtin', 'Use an existing built-in tool when its scope fits', 'Built-in tools can avoid unnecessary custom integration for supported local operations. They do not automatically reach arbitrary private services or bypass permissions.')
t('business', 'Explain the non-retryable business-rule outcome', 'A policy rejection is not normally fixed by repeating the same operation. Communicate the reason and legitimate next steps without evasion.')
t('cache', 'Use supported prompt-prefix caching for eligible repeated input', 'Caching may reduce repeated prefix processing under provider-specific rules. It does not extend the context window, update model weights, or verify an answer.')
t('cache006', '0.06% of input tokens were cache reads', 'A proportion must be multiplied by 100 to express a percentage; unit conversion errors can distort monitoring.')
t('cache100', '100% of input tokens were cache reads', 'All categorized input would need to be read from cache for a 100% share. Some matching text alone is insufficient.')
t('cache40', '40% of input tokens were cache reads', 'The non-read share differs from the read share when the categories are disjoint and exhaustive.')
t('cache60', '60% of input tokens were cache reads', 'If 60,000 of 100,000 categorized input tokens were cache reads, the share is 60%. A read share is not automatically the same percentage in monetary savings.')
t('cachemetric', 'Verify cache reads, writes, and economics in actual usage', 'Repeated text does not prove cache reuse. Check eligible matching, expiration, thresholds, and current prices before claiming savings.')
t('calibrate', 'Calibrate field-confidence thresholds against labeled examples', 'Reported confidence is a signal to validate empirically, not a probability guarantee. Calibration must reflect actual document and field distributions.')
t('canary', 'Canary a version change with regression gates and rollback', 'Stage exposure to the new configuration, compare required outcomes, and retain a known-good path. A vendor release note is not workload validation.')
t('cancel', 'Cancel local work and reconcile any external operation separately', 'Local cancellation limits waiting or computation but does not guarantee the server stopped or a remote side effect was rolled back.')
t('category', 'Temporarily disable a noisy category while repairing and evaluating it', 'A narrowly controlled pause can restore trust while the category is improved. Preserve valuable other categories and monitor the consequences.')
t('chain', 'Use a predictable sequence of specialized stages', 'A fixed pipeline fits a known set of dependent transformations. It is different from adaptive investigation whose next task depends on new discoveries.')
t('chaining', 'Break the task into linked checked prompt stages', 'Prompt chaining can isolate extraction, validation, and drafting when stages have known dependencies. Validate intermediate results rather than propagate errors blindly.')
t('checkpoint', 'Checkpoint durable state at safe workflow boundaries', 'Recovery needs committed progress, pending actions, evidence versions, and consistent artifacts. Checkpointing conversation text alone does not establish transaction completion.')
t('clienttool', 'Execute a client-defined tool through the application harness', 'The model proposes supported client tool calls; the application validates, authorizes, executes, and returns correlated results. A proposal alone does not execute application code.')
t('codereview', 'Review generated changes as ordinary production code', 'Inspect correctness, maintainability, dependencies, tests, and security. Generated code is not exempt from normal engineering review or accountable approval.')
t('command', 'Use a project-scoped custom slash command', 'The guide describes .claude/commands/ for shared invocable commands. User-scoped commands are personal; feature details depend on Claude Code version.')
t('community', 'Evaluate a maintained existing integration before writing a custom server', 'A suitable standard integration may reduce work. Assess security, permissions, maintenance, and requirements before adoption; custom tools remain appropriate for unique workflows.')
t('compact', 'Compact context while preserving checked facts and open issues', 'Compaction can reduce accumulated exploration, but summaries can be lossy. Validate critical state and preserve durable pointers to evidence.')
t('config', 'Separate environment configuration from application logic', 'Validate configuration at startup and keep environments explicit. Do not hard-code secrets or assume development and production identifiers are interchangeable.')
t('conflict', 'Preserve conflicting source values with an explicit flag', 'A conflict record enables review and prevents a synthetic answer from hiding disagreement. A valid schema alone does not resolve the underlying facts.')
t('constraint', 'Expose a constrained domain-specific operation', 'A narrow operation can enforce permitted sources, destinations, or actions more reliably than a general arbitrary-command or unrestricted-fetch interface.')
t('contested', 'Represent credible disagreement with attributed values', 'Do not average incompatible measurements or choose one arbitrarily. Preserve context and distinguish contested findings from established ones.')
t('context', 'Pass relevant evidence and constraints explicitly', 'Fresh subagents should receive the task-relevant findings, restrictions, and source metadata they need. Do not assume automatic access to the full parent conversation; fork semantics differ.')
t('contracttest', 'Test the integration contract at the provider boundary', 'Check serialized requests, content blocks, status handling, and representative responses. Mock success alone may not reveal a malformed real request or unsupported provider feature.')
t('count', 'Use supported token counting before oversized submission', 'A token-count endpoint or compatible estimator can help plan requests. Include hidden overhead allowed by the documented interface and verify actual usage afterward.')
t('coverage', 'Annotate evidence coverage and unavailable sources', 'A report can proceed with supported partial results if it clearly distinguishes established conclusions from gaps. Silence falsely implies complete coverage.')
t('criteria', 'State explicit reportable and non-reportable criteria', 'Concrete categories, severity thresholds, and exclusions are more actionable than vague requests to be careful. Evaluate precision and recall rather than assume compliance.')
t('customid', 'Correlate batch outcomes by custom_id', 'Stable unique request identifiers connect results to inputs without assuming arrival order. Validate uniqueness and retain a manifest.')
t('customloop', 'Implement a custom Messages-based agent harness', 'A custom harness gives the application direct control over requests, tool dispatch, stopping, state, and recovery. The application owns the resulting protocol and operational responsibilities.')
t('customtool', 'Implement an application-local tool for a specific integration', 'A local function tool can fit the needs of one application without deploying an MCP service. Still define schemas, authorization, error behavior, and tests.')
t('dates', 'Preserve collection and publication dates with claims', 'Different measurement periods can explain apparent disagreements. Dates and methodology should remain attached rather than being stripped in summaries.')
t('definition', 'Configure the subagent description, prompt, and tool scope', 'An agent definition separates when to delegate, what the specialist should do, and which tools it can use. SDK option names are version-specific.')
t('delimiter', 'Separate instructions and source data with explicit labels', 'Delimiters improve clarity about source boundaries but are not a security barrier or a grant of authority to the enclosed content.')
t('delta', 'Tell the resumed agent what changed and recheck affected evidence', 'Targeted re-analysis works when most prior context remains useful. Explicit change information prevents reliance on stale file or tool observations.')
t('deprecation', 'Plan a tested migration before model or API retirement', 'Pinning helps reproducibility only while that version remains supported. Track retirement notices and validate a supported replacement before the deadline.')
t('describe', 'Clarify tool purpose, inputs, outputs, and boundaries', 'Useful descriptions explain when to use a tool and how it differs from neighbors. Reliable selection needs more than names or generic one-line descriptions.')
t('direct', 'Implement a small well-understood change directly', 'A narrow fix with known requirements may not need a long planning phase. Tests and review still apply.')
t('directory', 'Use directory-scoped CLAUDE.md for a local package', 'Local instructions fit conventions tied to a particular subtree. Cross-directory filename patterns may be better served by path-scoped rules.')
t('discover', 'Check connected-server discovery and effective availability', 'Configured servers can expose tools together when connected, but server failure, approval, filtering, and permissions can affect what is actually usable.')
t('dynamic', 'Select specialists according to the actual task', 'Dynamic routing avoids invoking every specialist for a simple request. Selection should follow coverage needs, not a fixed ritual.')
t('edit', 'Use Edit with a verified unique anchor', 'Targeted replacement is suitable when current text can be identified uniquely. Ambiguous anchors can change the wrong location or fail.')
t('effort', 'Evaluate supported reasoning effort controls', 'Effort settings influence supported reasoning behavior under a particular model contract. They are not synonyms for sampling temperature or guarantees of correctness.')
t('egress', 'Restrict network destinations and prevent unsafe fetch paths', 'Enforce approved destinations and address handling to reduce exfiltration and SSRF risk. A friendly tool name or URL string check alone is not enough.')
t('empty', 'Represent a successful query with no matches explicitly', 'An empty successful result means no matching records were found under the query. It is distinct from a timeout or permission failure.')
t('end', 'Treat end_turn as the end of the current assistant turn', 'This indicates ordinary turn completion, not that every business objective or external action succeeded. Application acceptance checks still apply.')
t('env', 'Reference runtime environment variables instead of committing tokens', 'Environment expansion can keep literal secrets out of project files. Supply credentials through an approved secret path and protect logs as well.')
t('error', 'Return a structured tool error with category and retryability', 'An error contract should identify failure class, recoverability, and useful context. MCP isError marks an execution failure; it should not disguise a valid empty result.')
t('eval', 'Use a versioned representative held-out evaluation set', 'Include actual task variation, important failures, and acceptance criteria. Keep tuning cases separate and track changes to avoid evaluating only familiar demonstrations.')
t('examples', 'Provide concrete input–output examples', 'Examples clarify expected transformations when prose is interpreted inconsistently. Include boundaries and varied cases instead of only ideal examples.')
t('explore', 'Delegate focused exploration to a read-oriented subagent', 'Discovery can be isolated so verbose file output does not overwhelm the main conversation. Return useful findings and source pointers.')
t('facts', 'Preserve exact transactional facts outside lossy summaries', 'Keep verified amounts, identifiers, dates, and commitments in structured state. General summaries can omit details that later decisions depend on.')
t('failed', 'Resubmit only failed items after diagnosing their errors', 'Targeted resubmission avoids repeating successes and allows input fixes. Track identities and protect downstream effects against duplicate processing.')
t('few', 'Use representative few-shot examples with boundaries', 'A small varied demonstration set can teach format and judgment. Include near-miss cases and valid negatives so the model can generalize distinctions.')
t('fewshot', 'Provide several representative demonstrations', 'Few-shot examples illustrate task patterns in context. They should cover meaningful boundaries rather than merely repeat one ideal answer.')
t('final', 'Use the final assembled message and completion status', 'SDK accumulation helpers can provide the complete message. Inspect termination and errors before treating the resulting object as accepted application output.')
t('fixtures', 'Provide existing tests and approved fixtures', 'Relevant test context helps generation avoid duplicates and use valid repository conventions. Do not invent unavailable helper functions or external test data.')
t('force', 'Force the required named tool for that turn', 'Where supported, named tool selection requires the specified tool. Additional workflow ordering and authorization still belong in application code.')
t('fork', 'Fork an independent branch from a valid shared baseline', 'Forking supports divergent explorations without overwriting the original conversation. It does not itself isolate external files or undo side effects.')
t('format', 'Specify deterministic normalization rules and preserve originals when needed', 'Date, unit, and string normalization should be explicit and should not conceal source uncertainty. Validate transformations instead of guessing locale.')
t('framework', 'Choose a framework for needed orchestration semantics', 'Evaluate state graphs, typed validation, tracing, ecosystem, and deployment fit across frameworks such as LangGraph, Strands, or PydanticAI. A framework does not guarantee safety or correctness.')
t('fresh', 'Start a fresh session with a checked structured summary', 'A new context can avoid stale tool results when assumptions changed widely. Preserve verified facts, relevant constraints, and pointers rather than import all obsolete history.')
t('front', 'Present key findings early and organize supporting details', 'A structured overview and clear sections help reduce long-input position effects. Placement is a mitigation, not proof that every fact will be used.')
t('gap', 'Evaluate coverage and delegate targeted follow-up work', 'The coordinator compares results with requirements, identifies missing evidence, and commissions focused work rather than blindly repeating the whole pipeline.')
t('gate', 'Enforce prerequisites in trusted execution code', 'A programmatic gate checks current identity, state, and business rules before an external action. Prompt instructions alone are not an authorization boundary.')
t('git', 'Track source changes with version control', 'Version control records reviewable history and enables collaboration and rollback of code artifacts. It does not automatically record every runtime setting or external side effect.')
t('glob', 'Use Glob for filename or path-pattern discovery', 'Glob discovers files by path patterns rather than searching their contents. It can identify candidates for later reading.')
t('grep', 'Use Grep for content-pattern searches', 'Content search finds symbols, strings, and imports inside files. It is distinct from matching filenames and paths.')
t('haiku', 'Evaluate Haiku for suitable speed- and efficiency-oriented tasks', 'Model-family positioning is a starting hypothesis, not proof of fit. Use a specific supported version and measure the required quality, cost, and latency.')
t('handoff', 'Create a structured handoff with facts, status, and next actions', 'The recipient needs verified identifiers, completed work, unresolved issues, supporting evidence, and recommended actions, especially when the full transcript is unavailable.')
t('hint', 'Provide argument-hint for invocation guidance', 'Argument hints help users supply needed parameters. They do not replace actual argument validation or supply missing business facts.')
t('history', 'Supply the relevant conversation state on subsequent requests', 'For a stateless request flow, the application provides necessary history or an accurate representation. Persistent platform features have their own semantics and retention rules.')
t('hosting', 'Choose execution hosting and operational ownership explicitly', 'An imported SDK does not determine who hosts workers, manages infrastructure, or handles operations. Assess actual hosted and self-hosted deployment contracts separately.')
t('httpmcp', 'Use a supported network MCP transport with explicit authentication', 'Network deployment requires the protocol version, transport, authentication, TLS, and session handling to match. Do not assume arbitrary raw sockets are interchangeable with MCP.')
t('hub', 'Route coordination through an orchestrator', 'A coordinator manages decomposition, routing, error handling, and aggregation in a hub-and-spoke design. Specialists need not communicate through uncontrolled peer channels.')
t('idempotent', 'Use a durable idempotency key for the same logical action', 'Where supported, repeated requests for one operation should resolve to one intended external effect. Generating a new key for each retry defeats duplicate protection.')
t('identity', 'Use distinct least-privilege workload identities', 'Separate workload identities constrain unnecessary shared authority and improve attribution. Verify granted permissions and credential handling for each operational role.')
t('imports', 'Use @imports to keep instruction content modular', 'Imports reference relevant supporting instruction files. Their actual loading and accessibility should be verified rather than assumed.')
t('incident', 'Activate coordinated incident response and recovery', 'Contain verified harm, investigate affected systems and data, recover safely, and communicate through accountable owners. Observation alone is not containment.')
t('independent', 'Use an independent reviewer without the generator rationale', 'Independent review reduces anchoring on the original solution. It still needs the specification, relevant code, and evidence; independence does not guarantee correctness.')
t('inputschema', 'Define and validate a precise input schema', 'Schemas specify types, required fields, enums, and constraints. Trusted code still checks authorization and semantic business rules.')
t('integration', 'Add a cross-file or cross-component integration pass', 'Local review finds local defects; a separate integration pass checks interactions, interfaces, and data flow across boundaries.')
t('interacting', 'Explain interacting issues together before revising', 'When fixes influence one another, provide the combined constraints and failure evidence. Independent issues can be addressed separately.')
t('interface', 'Select the Claude interface appropriate to the workflow', 'Claude Code, Desktop, consumer chat, APIs, and SDKs serve different interaction needs. Verify each interface contract instead of assume identical state, configuration, and capabilities.')
t('interview', 'Ask targeted design questions before implementation', 'An interview-style clarification step surfaces unknown assumptions and constraints. Use it when uncertainty materially affects design.')
t('isolated', 'Run specialists with separately scoped working contexts', 'Context isolation reduces unrelated material and can limit conversational access. It does not automatically isolate external files, credentials, or remote side effects.')
t('jsoncli', 'Use supported JSON output and schema CLI options', 'The guide describes --output-format json and --json-schema for machine-parseable CI results. Verify the installed version and check execution status as well as payload.')
t('latency', 'Measure end-to-end response latency', 'Measure the complete user-facing interval consistently, including relevant tool and queue time. Lower per-request price does not establish lower cost per successful outcome.')
t('launcher', 'Enable the version-appropriate subagent invocation tool', 'Delegation requires a permitted launcher under the installed SDK contract. Check Agent versus legacy Task identifiers rather than assume all versions accept the same names.')
t('layered', 'Layer prevention, detection, approval, and recovery controls', 'No one prompt or content filter covers all attack paths. Combine least privilege, trusted checks, telemetry, tests, and incident response.')
t('length', 'Set a supported maximum generated-output length', 'An output ceiling bounds generation subject to model accounting. It does not itself expand input context or guarantee that a complete response fits.')
t('lifecycle', 'Plan deployment, operation, maintenance, and retirement', 'Development does not end at a successful API call. Include monitoring, updates, recovery, ownership, and decommissioning in the system lifecycle.')
t('loaded', 'Inspect which instruction files are actually loaded', 'The guide mentions /memory; current documentation also describes /context. Use the available inspection mechanism to diagnose scope and loading, not just the presence of a file.')
t('localretry', 'Recover transiently within the worker, then report unresolved failure', 'Bounded local recovery reduces coordinator noise. Exhausted recovery should preserve attempts, partial results, and alternatives rather than silently disappear.')
t('loop', 'Inspect stop_reason and dispatch the appropriate branch', 'The loop follows protocol stop reasons, executes permitted requested tools, and returns observations before continuing. Text appearing in a response does not establish completion.')
t('managed', 'Compare hosting responsibility, control, and service constraints', 'Self-hosting and managed deployment place different responsibilities on operations, networking, identity, and lifecycle. Availability and supported features must be verified.')
t('manifest', 'Resume from a checked manifest of worker states and artifacts', 'Recovery needs known state locations, completion status, source versions, and pending work. Do not infer completion merely because an output file exists.')
t('mcpclient', 'Have an MCP client connect to the server and invoke permitted capabilities', 'The client discovers and calls server-exposed capabilities under supported protocol and authorization. A model does not independently contact every backend without an integration.')
t('mcpprompt', 'Expose a reusable prompt template through MCP', 'MCP prompts package reusable interaction templates. They differ from resources providing content and tools executing operations.')
t('mcpserver', 'Implement a protocol-compatible server for approved capabilities', 'An MCP server exposes tools, resources, or prompts over supported transports and owns clear contracts. Reuse and security require deliberate deployment and permission design.')
t('memory', 'Retrieve application-managed memory into later context', 'Persisted preferences or facts can be selected and supplied to later requests. That continuity is external state management rather than automatic updates to model training weights.')
t('messages', 'Build a valid Messages API request with explicit content blocks', 'Use the selected API contract for model, instructions, messages, and typed content. Do not assume a consumer chat interface and a developer API share implicit state.')
t('modeltest', 'Select the least costly configuration that meets required outcomes', 'Compare supported models on representative quality, latency, safety, and operational constraints. Never optimize price while ignoring unacceptable failures.')
t('monitor', 'Monitor production service and outcome signals', 'Observe deployed latency, failures, drift, and task outcomes with accountable response thresholds. Monitoring differs from an offline evaluation or a single diagnostic trace.')
t('multipass', 'Separate local analysis from cross-file integration review', 'Focused passes reduce attention dilution while integration review checks interactions. Manage deduplication and reconcile findings before release.')
t('negative', 'Include valid examples that should not be flagged', 'Negative examples teach a boundary and can reduce repeated false positives. They should not teach blanket suppression of an entire genuine-risk category.')
t('network', 'Segment network zones between services', 'Network segmentation limits movement between execution environments. It does not by itself validate every URL, authorize business actions, or replace specific egress controls.')
t('nondeterminism', 'Allow for output variability and validate outcomes', 'Repeated calls can differ, even with low sampling settings. Seeds or low temperature do not establish universal cross-version determinism or factual accuracy.')
t('normalize', 'Normalize tool observations before model consumption', 'A post-tool processing step can standardize timestamps, statuses, units, and field shapes while preserving meaning and provenance. It is too late to block an action already executed.')
t('nullable', 'Allow explicit unknown or absent values in the schema', 'An optional field may be omitted; a nullable field may contain null. Design missing-data behavior deliberately instead of forcing invented values.')
t('oneshot', 'Provide one representative demonstration', 'One-shot prompting includes one example. It is different from a training update and may not cover important task variation.')
t('opus', 'Evaluate Opus for demanding capability-oriented work', 'A high-capability model may help difficult tasks, but size or family alone does not guarantee accuracy, acceptable latency, or economical deployment.')
t('other', 'Use an extensible category plus a detail field', 'An other category with details can represent valid cases outside an enum. Unclear represents uncertainty and should not be confused with known-but-uncatalogued categories.')
t('outputsafe', 'Treat model output as untrusted before rendering or execution', 'Use destination-appropriate escaping, validation, and permission checks. Valid JSON can still contain executable or malicious values.')
t('ownership', 'Assign operational owners and escalation responsibilities', 'Define who handles uncertain results, incidents, updates, and recovery. A model cannot substitute for accountable organizational responsibility.')
t('p95', 'Measure tail latency as well as average latency', 'An acceptable mean can hide slow requests that violate user requirements. Define percentile measurements and end-to-end boundaries consistently.')
t('parallel', 'Run independent branches concurrently and join checked results', 'Independent work can be parallelized within resource limits. A join must account for missing, failed, or conflicting outputs.')
t('partition', 'Assign distinct scopes and explicit coverage responsibilities', 'Non-overlapping assignments reduce duplicated research while a coverage checklist helps prevent missing important aspects.')
t('paths', 'Scope a rule with YAML paths glob patterns', 'Path-scoped rules apply to matching work rather than every task. Globs can cover files with the same role across different directories.')
t('pattern', 'Record detected_pattern and dismissal reasons', 'Structured finding metadata enables analysis of recurring false positives and targeted prompt improvement. A generic accept/reject count loses diagnostic detail.')
t('permission', 'Stop the unauthorized operation and use an approved access path', 'Permission denial does not justify trying alternate credentials or leaking restricted content. Recover only through explicitly authorized mechanisms.')
t('personal', 'Put personal cross-project preferences in ~/.claude/CLAUDE.md', 'User-level instructions apply to that user rather than automatically to everyone cloning the repository. Do not place shared team standards only here.')
t('pii', 'Minimize, redact, and restrict sensitive data by approved purpose', 'Collect and expose only necessary personal information, including in tool outputs, traces, and test data. A blacklist alone does not establish privacy.')
t('pin', 'Pin compatible model, SDK, prompt, and dependency versions', 'Reproducible configuration requires identifying all behavior-relevant versions. A pinned model alone does not freeze application code, prompts, or provider behavior forever.')
t('plan', 'Use plan mode to investigate and compare approaches', 'Planning fits uncertain architectural or multi-file changes before implementation. It is not evidence that a change has been executed or tested.')
t('plugin', 'Version and review plugin dependencies and permissions', 'Plugins can change tools and workflow behavior. Track provenance, versions, compatibility, and permissions rather than install unreviewed code merely because a model suggests it.')
t('prefix', 'Put eligible stable common content before variable input for cache reuse', 'Supported prefix caching depends on exact eligible content, placement, checkpoints, model, and service rules. It is not a cross-user final-answer cache.')
t('pregate', 'Use pre-execution tool interception for blocking policy checks', 'An appropriate pre-tool hook or equivalent trusted gate can deny a disallowed action before it runs. Hook implementation and failure handling must be tested.')
t('preserve', 'Preserve protocol-required blocks through tool continuations', 'When a model or feature requires returned context or signed thinking blocks, follow that version-specific contract. Do not edit signed blocks or manufacture hidden reasoning.')
t('print', 'Run Claude Code in non-interactive print mode', 'The -p or --print mode is intended for non-interactive runs. Authentication, permissions, termination, and artifact capture still require CI configuration.')
t('prior', 'Pass prior findings and request only new or unresolved issues', 'Comparing the current diff with prior findings can reduce duplicate review comments. Preserve still-valid findings rather than simply suppressing all repeats.')
t('privacy', 'Apply a privacy-preserving aggregate release mechanism', 'Statistical privacy mechanisms may protect aggregate publication under their assumptions. They do not replace purpose-limited collection, requester authorization, or operational secret management.')
t('project', 'Put shared project standards in versioned CLAUDE.md', 'Root CLAUDE.md or .claude/CLAUDE.md can distribute project instructions to teammates. These are contextual guidance, not a hard security policy.')
t('promptaudit', 'Inspect conflicting routing instructions as well as tool descriptions', 'System-prompt keywords can misroute requests even when tool contracts are reasonable. Diagnose both instruction and interface effects.')
t('promptspec', 'Specify task, audience, constraints, and output expectations', 'Concrete requirements clarify what useful output means. A role, sampling setting, or longer answer limit does not replace a precise task contract.')
t('promptversion', 'Version exact prompt content and its dependencies', 'Record revisions of behavioral instructions with evaluation and release history. A model pin does not freeze changing application prompts.')
t('propagate', 'Return structured failure context and partial results', 'The coordinator needs failure type, attempted operation, useful outputs, and alternatives. A failure must not be disguised as a successful empty search.')
t('provenance', 'Preserve claim-to-source mappings through every handoff', 'Claims need traceable source identities, relevant excerpts, locations, and dates as applicable. A bibliography without claim mappings can lose attribution.')
t('provider', 'Verify the actual hosting provider contract', 'Check endpoints, authentication, model identifiers, capabilities, data terms, and feature support for the selected provider. Shared model branding does not guarantee identical APIs or policies.')
t('read', 'Use Read to inspect current file contents', 'Inspecting current contents supplies evidence and reliable anchors before modification. A filename search alone does not reveal implementation behavior.')
t('realtime', 'Use a synchronous interactive request path', 'An interactive path suits work needing a prompt response within its service targets. It is distinct from deferred batch submission and does not guarantee arbitrary latency.')
t('redteam', 'Test adversarial and misuse scenarios', 'Probe injection, bypasses, harmful tool combinations, and failures beyond friendly expected inputs. Finite adversarial testing does not prove that every future attack is prevented.')
t('refactor', 'Refactor internal structure while preserving required behavior', 'Refactoring changes implementation organization without intended external behavior changes. Tests and review help detect accidental regressions.')
t('release', 'Manage release approval and rollback boundaries', 'Record the deployable configuration, approval gates, and a practical known-good recovery path. Deployment is an operational change rather than just a successful local build.')
t('render', 'Use representations suited to the content type', 'Tables can preserve financial comparisons, while prose and structured lists suit other needs. A single forced format can hide important structure.')
t('requestid', 'Propagate correlation identifiers across requests and tools', 'Link a user task to provider requests, worker runs, and actions without using sensitive content as an identifier. Protect telemetry access and retention.')
t('requirements', 'Translate business goals into measurable functional and operational requirements', 'Specify behavior, latency, throughput, data constraints, failure policy, and acceptance criteria. A model or framework choice is not a substitute for requirements.')
t('reserve11', '11,000 tokens', 'A hypothetical shared 16,000-token budget minus 3,000 instructions/history and 2,000 reserved generation leaves 11,000 for evidence. Real service accounting must be verified.')
t('reserve13', '13,000 tokens', 'Subtracting instructions alone omits the explicit generation reservation under a shared-budget assumption.')
t('reserve14', '14,000 tokens', 'Subtract every specified budget component rather than reserve only output and ignore instructions or history.')
t('reserve16', '16,000 tokens', 'Total context capacity is not all available for evidence when instructions, history, and generation share the stated budget.')
t('resource', 'Expose a supported MCP resource catalog', 'Resources can expose content or metadata such as document hierarchies and database schemas. They are not interchangeable with actions executed as tools.')
t('rest', 'Apply HTTP method, status, authentication, and payload contracts', 'A REST integration must respect its actual endpoint contract. HTTP 200 does not establish that the requested business operation succeeded semantically.')
t('result', 'Append the assistant tool-use blocks and matching tool results', 'Client-tool observations must be returned with the correct tool-use identifiers in a valid message sequence so Claude can use actual results.')
t('resume', 'Resume the identified session when its context remains valid', 'Resumption can reuse prior analysis when still accurate. The session identity and current external state must be verified; resumption is not automatic freshness.')
t('retention', 'Review the exact service data-use and retention controls', 'Parameter freezing does not imply no logs, abuse monitoring, stored history, or caches. Review provider, plan, region, settings, and contractual obligations.')
t('retry', 'Retry with the document, failed result, and specific validation errors', 'Actionable feedback supports correction when evidence exists. Bound attempts and validate the revised result rather than resubmit the same vague request indefinitely.')
t('retrybudget', 'Coordinate retries across SDK and application layers', 'Nested automatic retries can multiply attempts and latency. Set a shared attempt or elapsed-time budget and inspect SDK defaults.')
t('review', 'Route ambiguous, conflicting, or high-risk cases to qualified review', 'Review priority should reflect uncertainty and consequences. A high uncalibrated confidence number should not override contradictory evidence.')
t('riskreview', 'Assess impact, data, authority, and misuse risks before deployment', 'Risk review identifies consequences and necessary controls before capability is granted. Ordinary quality evaluation alone may omit regulatory, privacy, and misuse concerns.')
t('role', 'Assign a relevant role or perspective in the prompt', 'A role can guide style and viewpoint, but it does not grant expertise, authorization, or verified knowledge.')
t('rotate', 'Revoke exposed credentials and investigate their use', 'Secret exposure requires containment and appropriate incident investigation, rotation, affected-copy handling, and monitoring. Removing one visible copy is not sufficient.')
t('route', 'Route requests using evaluated task classes and safe fallbacks', 'Use evidence-based routing to suitable configurations, monitor misclassification, and define fallback. Routing complexity must justify its own operating cost.')
t('rules', 'Organize focused conventions in .claude/rules/', 'Topic-specific rule files reduce one oversized instruction document. Add path scoping when a rule is only relevant to selected files.')
t('safety', 'Apply content-level safety detection and moderation', 'Content controls address applicable unsafe-content categories. They are not a replacement for identity checks, resource authorization, constrained tools, or secure execution.')
t('sample', 'Tune and validate on a representative sample before large submission', 'A small development sample reveals systematic extraction problems before multiplying them across the full dataset. Independent evaluation is still needed.')
t('sampling', 'Account for probabilistic generation and output variability', 'Next-token generation may yield different plausible results across calls. Validate required outcomes rather than assume ordinary inference changes persistent model memory.')
t('sanitize', 'Validate and encode untrusted values for their destination', 'Model-generated strings are not safe SQL, shell, HTML, or filenames by default. Prefer parameterized operations, output encoding, and constrained execution paths.')
t('scope', 'Give each specialist only task-relevant tools', 'Role-appropriate tools reduce selection ambiguity and unnecessary authority. Tool scoping complements, not replaces, external permission checks.')
t('scratch', 'Persist concise codebase findings with file and symbol pointers', 'Durable notes counter context degradation and support later verification. Record source versions or change cues so notes are not mistaken for permanently current truth.')
t('sdkwrapper', 'Use an SDK wrapper over the provider request contract', 'An SDK can simplify serialization, accumulation, and error handling. The actual provider schema, policies, supported features, and operational limits still apply.')
t('secrets', 'Manage credentials in protected execution infrastructure', 'Keep credentials out of prompts, repositories, generated output, and unprotected logs. Supply narrowly scoped credentials through approved runtime secret mechanisms.')
t('semantic', 'Validate extracted values against evidence and business rules', 'Valid syntax does not prove correct fields, sums, units, identities, or permitted actions. Semantic checks are needed before downstream use.')
t('sequence', 'Wait for validated prerequisite outputs', 'Dependent work must follow its prerequisites. Starting a dependent action early can use absent, stale, or unauthorized data.')
t('servertool', 'Use a supported provider-executed server tool', 'Supported built-in server tools execute within the provider service under that feature contract. They differ from application functions the client must dispatch itself.')
t('session', 'Design explicit user and conversation session boundaries', 'Keep relevant history and state associated with the correct user and task. Stateless model calls do not automatically maintain safe cross-user conversation persistence.')
t('settings', 'Use the appropriate settings.json scope for behavioral configuration', 'Claude Code settings configure supported behavior, permissions, hooks, and plugins. Shared .claude/settings.json, user, local, and managed scopes have distinct reach.')
t('severity', 'Define severity using impact and concrete examples', 'A consistent rubric distinguishes materially different harms. Self-reported confidence is not a substitute for severity or business impact.')
t('shared', 'Use a shared multi-agent working context', 'Shared context can support collaboration but needs coordination, scope, and concurrency controls. It differs from a supervisor owning delegation and reconciling final outputs.')
t('sharedmcp', 'Use project-scoped .mcp.json for shared server configuration', 'Versioned project configuration can distribute team tooling. Keep real credentials outside Git and check approvals and environment requirements.')
t('skill', 'Put an on-demand workflow in a project skill', 'A versioned .claude/skills/<name>/SKILL.md can package task-specific guidance. Keep universally relevant standards in project instructions rather than only in an optional skill.')
t('skillfork', 'Use context: fork for isolated skill execution', 'Where supported, an isolated skill context contains intermediate exploration. It does not automatically provide filesystem isolation or remove tool-permission obligations.')
t('skilltools', 'Configure a least-privilege skill workflow and verify effective permissions', 'Use supported workflow configuration and actual runtime permission controls. A skill allowed-tools declaration can affect pre-approval; it must not be assumed to create a hard sandbox or deny every other tool by itself.')
t('slo', 'Define observable service-level objectives and failure behavior', 'Set measurable latency, availability, and quality targets for the complete workflow. Account for dependencies and tail behavior rather than only average model speed.')
t('sonnet', 'Evaluate Sonnet for a measured balance of capability and efficiency', 'A balanced model may suit many development workflows, but the actual selected release and workload requirements determine fitness.')
t('specific', 'Delegate a focused codebase question with a bounded output', 'A concrete question such as tracing one authorization path gives useful coverage with less irrelevant exploration than asking every worker to read everything.')
t('split', 'Separate genuinely different tasks into clearly bounded tools', 'A generic interface can be split when its unrelated responsibilities cause ambiguity. Do not multiply near-identical tools without a meaningful boundary.')
t('sse', 'Consume the Messages stream as server-sent events', 'The documented streaming interface emits SSE events over HTTP. It is not inherently a WebSocket connection or one valid JSON object per arbitrary network chunk.')
t('stakeholder', 'Identify affected users and accountable stakeholders', 'Consult people who use, operate, approve, or are materially affected by a workflow. Requirements should reflect real responsibilities rather than assumptions made by implementers alone.')
t('state', 'Persist structured task state and pending actions', 'Durable state records facts, progress, outputs, and unresolved operations across interruptions. Conversation prose alone is not a reliable transaction log.')
t('stdio', 'Use stdio for a suitable local subprocess MCP connection', 'Protocol messages use the standard streams defined by the transport. Keep diagnostic logging off protocol stdout so clients can parse messages reliably.')
t('strata', 'Evaluate accuracy by document type and field segment', 'Averages can hide systematic failures in rare forms or important fields. Segment-level evaluation informs safe automation and review allocation.')
t('streamerror', 'Handle errors after streaming has already begun', 'A successful HTTP setup does not prove stream completion. Detect error events or interrupted streams, preserve status, and avoid publishing partial results as final success.')
t('strict', 'Use supported strict structured output with a schema', 'Constrained schema support targets structural compliance for supported schemas and response modes. Handle refusals, truncation, and compatibility; factual correctness is separate.')
t('sync', 'Use synchronous requests for blocking latency-sensitive work', 'Blocking user or pre-merge flows need an appropriate timely request path. Synchronous execution still needs timeouts and failure policy.')
t('system', 'Place trusted application policy in the supported system instruction field', 'Keep trusted instructions separate from user and retrieved data. On the direct Messages API, system instructions use the top-level system parameter rather than a system-role entry in messages.')
t('temperature', 'Adjust sampling variability, not factual truth', 'Temperature changes next-token sampling behavior where supported. Lowering it does not independently guarantee correct extraction, grounding, or identical execution.')
t('testdouble', 'Use controlled stubs for repeatable failure-path tests', 'Inject timeouts, malformed responses, and provider failures without live side effects. Combine with contract and representative integration tests rather than infer complete correctness from mocks.')
t('tests', 'Use tests and specific failure feedback to drive iteration', 'Expected behavior and edge cases make revisions checkable. A passing narrow suite is not proof of complete correctness or security.')
t('thinking', 'Use supported thinking or effort controls after measuring task benefit', 'Reasoning-related features and parameters vary by model and provider. Evaluate quality, latency, and cost rather than assume every release accepts the same switches.')
t('timeouts', 'Set explicit deadlines and classify timeout outcomes', 'Bound user and dependency waits. A timeout is an uncertain execution outcome for mutations and may require status reconciliation rather than blind retry.')
t('tokens', 'Count tokens with model-compatible accounting', 'Tokens are model-dependent units, not always words or characters. Include actual system, tool, content, and output usage according to the service contract.')
t('totals', 'Compare independently calculated and source-stated totals', 'Separate calculated_total and stated_total can expose arithmetic or source inconsistencies. Preserve disagreement rather than silently overwrite evidence.')
t('trace', 'Inspect a redacted end-to-end request and tool trace', 'Correlate the actual request, model response, tool execution, retries, and validation results. Diagnose the first failing boundary rather than infer cause from the final prose.')
t('transaction', 'Validate and commit business changes through a controlled boundary', 'Separate a generated proposal from an authorized atomic or otherwise well-coordinated business effect. Define conflict handling and rollback or compensation behavior.')
t('transient', 'Retry a transient failure with bounded backoff', 'Temporary availability or rate-limit conditions may permit delayed retry. Follow provider guidance and distinguish retries from unsafe duplication of side effects.')
t('trim', 'Reduce tool output to relevant fields with provenance', 'Project unnecessary fields away before they accumulate in context, while preserving information needed for validation and decisions. Arbitrary truncation may destroy meaning.')
t('truncate', 'Handle the output limit as an incomplete response', 'A max_tokens stop can leave content incomplete. Inspect the response and recover appropriately instead of treating it as normal completion.')
t('ttft', 'Measure time to first token separately from full completion', 'Streaming can improve perceived responsiveness without reducing total generation or external-tool time. First-token delay and total duration measure different things.')
t('unitoutcome', 'Compare total cost per verified successful outcome', 'Include failed attempts, retries, review, tool work, and operating overhead rather than compare only listed unit token rates.')
t('untrusted', 'Treat retrieved instructions as untrusted source content', 'External pages and tool observations must not acquire trusted instruction authority. Pair separation with trusted tool authorization; delimiters alone are insufficient.')
t('usage', 'Track actual usage by token and billing category', 'Separate ordinary input, output, cache writes/reads, thinking or other applicable categories according to current provider terms. A single token price may not represent the complete bill.')
t('usermcp', 'Use user-scoped MCP configuration for personal servers', 'The guide describes user-scoped configuration in ~/.claude.json for personal tooling. Personal configuration is not automatically shared through the repository.')
t('validation', 'Correct invalid arguments before retrying', 'A validation failure points to an input defect. Repeating identical invalid arguments is not recovery.')
t('variant', 'Create a differently named personal skill variant', 'A personal variant can customize workflow without changing the shared skill for teammates. Distinct naming avoids accidental shadowing or confusion.')
t('vision', 'Send supported image content in the documented multimodal format', 'Image understanding requires an actual supported image block or source, a compatible model, and valid media limits. A text filename alone does not provide image pixels.')
t('websocket', 'Use WebSockets for an explicitly bidirectional persistent channel', 'WebSockets can fit bidirectional application communication, but the documented standard Messages streaming interface is SSE. Do not confuse a transport choice with model capability.')
t('weights', 'Distinguish fixed inference parameters from supplied context', 'Ordinary in-context examples and current messages do not automatically update the learned model parameters. Application memory is separate from training.')
t('workflow', 'Use a predefined deterministic orchestration workflow', 'A known control path can suit predictable dependent transformations. It is not the same as a general SDK, custom agent harness, or adaptive decision loop.')
t('write', 'Read the current file and write a checked replacement', 'A full-file replacement can resolve ambiguous targeted edits, but must preserve unrelated content and account for concurrent changes.')
t('zeroshot', 'Provide a task instruction without demonstrations', 'Zero-shot prompting supplies no example input-output pairs. The model may still use its pretrained capabilities and the request context.')

t('fastmode', 'Evaluate supported fast inference mode', 'Fast-mode availability, pricing, and behavior depend on the selected service and model. Measure its latency and cost impact instead of assume it changes model capability, output length, or reasoning effort in a universal way.')
